use vstd::prelude::*;

verus! {

    // Returns a value r that is <= every element of the non‐empty slice `a`.
    fn min_array(a: &[i32]) -> (r: i32)
        requires
            a.len() > 0,
        ensures
            forall |k: usize| k < a.len() ==> r <= a[k],
    {
        // Initialize the minimum to the first element
        let mut min_val: i32 = a[0];
        // We'll scan from index 1 up to a.len()
        let mut i: usize = 1;
        while i < a.len()
            invariant
                // We never go past the end
                i <= a.len(),
                // min_val is <= every element we have seen so far
                forall |j: usize| j < i ==> min_val <= a[j],
            decreases
                a.len() - i,
        {
            let current = a[i];
            if current < min_val {
                min_val = current;
            }
            i = i + 1;
        }
        min_val
    }

}

fn main() {
    // example usage
    let xs: Vec<i32> = vec![-3, 7, 0, -5, 2];
    let m = min_array(&xs);
    assert!(m <= xs[0]);
    assert!(m <= xs[1]);
    assert!(m <= xs[2]);
    assert!(m <= xs[3]);
    assert!(m <= xs[4]);
}